# Let's try a smarter backtracking search with constraint propagation
# Order vertices by degree (most constrained first)

edges = []
for g in range(5):
    v0, v1, v2 = g*3, g*3+1, g*3+2
    edges.extend([(v0,v1),(v0,v2),(v1,v2)])
for g in range(4):
    for i in range(3):
        edges.append((g*3+i, (g+1)*3+i))

# Build adjacency
adj = [[] for _ in range(15)]
for u, v in edges:
    adj[u].append(v)
    adj[v].append(u)

print("Degrees:", [len(adj[i]) for i in range(15)])

# Edge lookup
edge_set = set(edges) | set((v,u) for u,v in edges)

def get_edge_diffs(labels):
    diffs = []
    for u, v in edges:
        if labels[u] is not None and labels[v] is not None:
            diffs.append(abs(labels[u] - labels[v]))
    return diffs

# Backtracking with forward checking
import sys
sys.setrecursionlimit(100000)

def solve():
    labels = [None] * 15
    used_labels = set()
    used_diffs = set()

    # Order: try to assign vertices in a connected order
    # Start with vertex 0, then expand
    order = list(range(15))

    def backtrack(idx):
        if idx == 15:
            return True

        v = order[idx]

        for lbl in range(28):
            if lbl in used_labels:
                continue

            # Check all edges with already-assigned neighbors
            new_diffs = []
            ok = True
            for nb in adj[v]:
                if labels[nb] is not None:
                    d = abs(lbl - labels[nb])
                    if d == 0 or d in used_diffs or d in new_diffs:
                        ok = False
                        break
                    new_diffs.append(d)

            if ok:
                labels[v] = lbl
                used_labels.add(lbl)
                for d in new_diffs:
                    used_diffs.add(d)

                if backtrack(idx + 1):
                    return True

                labels[v] = None
                used_labels.remove(lbl)
                for d in new_diffs:
                    used_diffs.remove(d)

        return False

    if backtrack(0):
        return labels
    return None

print("Starting backtracking...")
result = solve()
if result:
    print("Found:", result)
else:
    print("No solution found")
